// AUTO-GENERATED from the original baby-name-rater seed pipeline
// (SSA names -> Soundex dedup -> Claude Haiku enrichment). 4690 fully-enriched names.
// Embedded as base64 JSON and decoded at module load to avoid TS2590 on a huge typed literal.
export type SeedName = {
  name: string;
  origin?: string | null;
  meaning?: string | null;
  isBoy?: boolean;
  isGirl?: boolean;
  usRank?: number;
  worldRank?: number;
  phonetic?: string | null;
  syllableCount?: number | null;
  meaningTags?: string[];
  famousPerson1?: string | null;
  famousPerson2?: string | null;
  famousPerson3?: string | null;
  alternativeSpellings?: string[];
};

const DATA_B64 =
  "";

export const babyNames: SeedName[] = JSON.parse(
  Buffer.from(DATA_B64, "base64").toString("utf8")
);
